From eff0ed34bdae93ae92b8a1dbb3cafb03ad051299 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:17:56 +0100
Subject: [PATCH] klipper: don't read image data when images aren't saved

Items with both text and an image were saved whole even with image
saving off, so the clipboard read the image from the source app and
froze Plasma until it arrived. Now only their text is saved.

BUG: 490952
---
 klipper/configdialog.cpp       |  2 +-
 klipper/historymodel.cpp       | 25 +++++++++++++++++--------
 klipper/historymodel.h         |  2 +-
 klipper/updateclipboardjob.cpp |  6 +++++-
 klipper/updateclipboardjob.h   |  3 ++-
 5 files changed, 26 insertions(+), 12 deletions(-)

diff --git a/klipper/configdialog.cpp b/klipper/configdialog.cpp
index 592dfd8dd8..59d13b7393 100644
--- a/klipper/configdialog.cpp
+++ b/klipper/configdialog.cpp
@@ -153,7 +153,7 @@ GeneralWidget::GeneralWidget(QWidget *parent)
                                   "<nl/>"
                                   "Also note that the Spectacle screenshot tool will ignore this setting "
                                   "when configured to save screenshots to the clipboard. "
-                                  "Any application that sends both text and image will also ignore it."),
+                                  "When an application sends both text and an image, only the text is saved."),
                            imageHint);
     });
 }
diff --git a/klipper/historymodel.cpp b/klipper/historymodel.cpp
index 8112dadb5b..a3e8f86f54 100644
--- a/klipper/historymodel.cpp
+++ b/klipper/historymodel.cpp
@@ -33,6 +33,7 @@
 #include "historyitem.h"
 #include "klipper_debug.h"
 #include "klippersettings.h"
+#include "mimetypes.h"
 #include "systemclipboard.h"
 #include "updateclipboardjob.h"
 #include "urlgrabber.h"
@@ -157,7 +158,7 @@ void migrateSettings()
     }
 }

-QString computeUuid(const QMimeData *data)
+QString computeUuid(const QMimeData *data, bool withImage = true)
 {
     QCryptographicHash hash(QCryptographicHash::Sha1);
     if (data->hasText()) {
@@ -168,7 +169,7 @@ QString computeUuid(const QMimeData *data)
             hash.addData(url.toEncoded());
         }
     }
-    if (data->hasImage()) {
+    if (withImage && data->hasImage()) {
         const auto image = data->imageData().value<QImage>();
         hash.addData(QByteArrayView(reinterpret_cast<const char *>(image.constBits()), image.sizeInBytes()));
     }
@@ -758,13 +759,13 @@ static QString textFromMimeData(const QMimeData *mimeData)
     return urlText.join(u' ');
 }

-bool HistoryModel::insert(const QMimeData *mimeData, qreal timestamp)
+bool HistoryModel::insert(const QMimeData *mimeData, qreal timestamp, bool withImages)
 {
     if (m_maxSize == 0) {
         // special case - cannot insert any items
         return false;
     }
-    QString uuid = computeUuid(mimeData);
+    QString uuid = computeUuid(mimeData, withImages);
     if (uuid.size() != 40 /*SHA1*/) [[unlikely]] {
         return false;
     }
@@ -775,13 +776,16 @@ bool HistoryModel::insert(const QMimeData *mimeData, qreal timestamp)
     }

     QStringList formats = mimeData->formats();
+    if (!withImages) {
+        formats.removeIf(MimeTypes::isImage<QString>);
+    }
     if (formats.empty() || formats.size() > 50) [[unlikely]] {
         return false;
     }

     const QString text = textFromMimeData(mimeData);
     auto item = std::make_shared<HistoryItem>(uuid, formats, text);
-    auto updateJob = UpdateDatabaseJob::updateClipboard(this, &m_db, m_dbFolder, uuid, text, mimeData, timestamp);
+    auto updateJob = UpdateDatabaseJob::updateClipboard(this, &m_db, m_dbFolder, uuid, text, mimeData, timestamp, withImages);
     if (item->type() == HistoryItemType::Image) {
         connect(updateJob, &KJob::finished, this, [this, uuid](KJob *job) {
             if (job->error()) {
@@ -1077,11 +1081,16 @@ void HistoryModel::checkClipData(QClipboard::Mode mode, const QMimeData *data)
         return;
     }

-    if (!m_bSaveImages && data->hasImage() && !data->hasText() /*BUG 491488*/ && !data->hasFormat(QStringLiteral("x-kde-force-image-copy"))) {
-        return;
+    bool withImages = true;
+    if (!m_bSaveImages && data->hasImage() && !data->hasFormat(QStringLiteral("x-kde-force-image-copy"))) {
+        if (!data->hasText()) {
+            return;
+        }
+        // BUG 491488: keep the text, but don't request the image data, which can take a long time to arrive
+        withImages = false;
     }

-    if (insert(data)) [[likely]] {
+    if (insert(data, 0, withImages)) [[likely]] {
         qCDebug(KLIPPER_LOG) << "Synchronize?" << m_bSynchronize;
         if (m_bSynchronize) { // applyClipChanges can return nullptr
             m_clip->setMimeData(data,
