         const bool isImage = it == qtImageIt || format.startsWith(MimeTypes::imagePrefix);
         if (isImage) {
+            if (!withImages) {
+                continue;
+            }
             // Skip image formats after QImage/PNG because they're probably
             // generated on demand.
             // We keep PNGs even if they're generated from a QImage because PNGs
diff --git a/klipper/updateclipboardjob.h b/klipper/updateclipboardjob.h
index d02ed62598..7cff980b47 100644
--- a/klipper/updateclipboardjob.h
